function cardDoFeed(imagem) {
  const u = String(imagem || '');
  return /^https:\/\/\S+\/card\?d=/.test(u) ? `${u}&f=feed` : '';
}

function legendaDoFeed(oferta) {
  const nome = (String((oferta && oferta.texto) || '').split('\n')[2] || '').replace(/[*_~]/g, '').trim();
  if (!nome) return '';
  return [`\u{1F525} Oferta do dia: ${nome}`, '',
    'Preço visto hoje na loja. Pode mudar a qualquer momento.', '',
    '\u{1F449} O link do grupo grátis de ofertas no WhatsApp está na bio.', '',
    '#publi #ofertas #promocao #cupom #descontos'].join('\n');
}

async function publicarNoFeed(http, env, imagem, legenda) {
  if (!env.META_IG_USER_ID || !env.META_ACCESS_TOKEN || !imagem || !legenda) return null;
  const raiz = `https://graph.facebook.com/v21.0/${encodeURIComponent(env.META_IG_USER_ID)}`;
  const c = await http.httpRequest({ method: 'POST', url: `${raiz}/media`, json: true, timeout: 60000,
    body: { image_url: imagem, caption: legenda, access_token: env.META_ACCESS_TOKEN } });
  if (!c || !c.id) return null;
  for (let i = 0; i < 6; i++) {
    const st = await http.httpRequest({ method: 'GET', json: true, timeout: 15000,
      url: `https://graph.facebook.com/v21.0/${c.id}?fields=status_code&access_token=${encodeURIComponent(env.META_ACCESS_TOKEN)}` });
    if (!st || st.status_code === 'FINISHED') break;
    if (st.status_code === 'ERROR') return null;
    if (typeof setTimeout === 'function') await new Promise(r => setTimeout(r, 5000));
  }
  const r = await http.httpRequest({ method: 'POST', url: `${raiz}/media_publish`, json: true, timeout: 60000,
    body: { creation_id: c.id, access_token: env.META_ACCESS_TOKEN } });
  return (r && r.id) || null;
}

function avisoDaOfertaDoDia({ feedFalhou, storyFalhou }) {
  const quais = [feedFalhou && 'o post no feed', storyFalhou && 'o story'].filter(Boolean);
  if (!quais.length) return null;
  return ['⚠️ *Instagram: a oferta do dia não saiu inteira*', '',
    `Não consegui publicar ${quais.join(' nem ')} da oferta das 12h. O WhatsApp seguiu normal.`,
    'Amanhã ele tenta de novo sozinho.'].join('\n');
}



const horaSP = (agora) => Number(new Intl.DateTimeFormat('en-GB', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false }).format(agora));
const diaSP = (agora) => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(agora);

const horaDoConteudo = (agora) => horaSP(agora) >= 18 && horaSP(agora) < 22;

function postDeHoje(agenda, agora, mem) {
  const dia = diaSP(agora);
  const feitos = new Set(mem.feitos || []);
  const tent = mem.tentativas && mem.tentativas.dia === dia ? mem.tentativas : { dia, n: {} };
  mem.tentativas = tent;
  return (Array.isArray(agenda) ? agenda : []).find(p => p && p.data === dia && /^[a-z0-9-]+$/.test(String(p.id || ''))
    && (/^\/instagram\/[a-z0-9-]+\.jpg$/.test(String(p.imagem || '')) || /^\/instagram\/[a-z0-9-]+\.mp4$/.test(String(p.video || ''))) && String(p.legenda || '').trim()
    && !feitos.has(p.id) && (tent.n[p.id] || 0) < 3) || null;
}

function anotarTentativa(mem, id, publicado) {
  if (publicado) mem.feitos = [...(mem.feitos || []).filter(x => x !== id), id].slice(-120);
  else mem.tentativas.n[id] = (mem.tentativas.n[id] || 0) + 1;
}

const reelLigado = (env) => String((env && env.INSTAGRAM_REEL) || '').trim().toLowerCase() === 'sim';

async function publicarReel(http, env, video, legenda) {
  if (!env.META_IG_USER_ID || !env.META_ACCESS_TOKEN || !video || !legenda) return null;
  const raiz = `https://graph.facebook.com/v21.0/${encodeURIComponent(env.META_IG_USER_ID)}`;
  const c = await http.httpRequest({ method: 'POST', url: `${raiz}/media`, json: true, timeout: 60000,
    body: { media_type: 'REELS', video_url: video, caption: legenda, share_to_feed: true, access_token: env.META_ACCESS_TOKEN } });
  if (!c || !c.id) return null;
  let pronto = false;
  for (let i = 0; i < 24 && !pronto; i++) {
    const st = await http.httpRequest({ method: 'GET', json: true, timeout: 15000,
      url: `https://graph.facebook.com/v21.0/${c.id}?fields=status_code&access_token=${encodeURIComponent(env.META_ACCESS_TOKEN)}` });
    if (st && st.status_code === 'ERROR') return null;
    pronto = !st || st.status_code === 'FINISHED';
    if (!pronto && typeof setTimeout === 'function') await new Promise(r => setTimeout(r, 5000));
  }
  if (!pronto) return null;
  const r = await http.httpRequest({ method: 'POST', url: `${raiz}/media_publish`, json: true, timeout: 60000,
    body: { creation_id: c.id, access_token: env.META_ACCESS_TOKEN } });
  return (r && r.id) || null;
}

function avisoDeFalha(p, tentativas) {
  if (!p || tentativas !== 3) return null;
  return ['⚠️ *Instagram: o post de hoje não saiu*', '',
    `${p.video ? 'O Reel' : 'O post'} "${p.id}" falhou nas 3 tentativas (18h às 22h) e não sai mais hoje.`,
    'Para remarcar, mude a data dele na agenda (marketing/instagram/posts.json).'].join('\n');
}

const mem = $getWorkflowStaticData('global');
const agora = new Date();
// Rodado na mão no editor: mostra o que sairia hoje e não publica.
const teste = typeof $execution !== 'undefined' && /^(test|manual)$/.test($execution.mode);
if (String($env.INSTAGRAM_FEED || '').trim().toLowerCase() !== 'sim' && !teste) return [{ json: { publicou: false, motivo: 'desligado' } }];
if (!horaDoConteudo(agora) && !teste) return [{ json: { publicou: false, motivo: 'fora_do_horario' } }];
let agenda = null;
try { agenda = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.temdescontos.com.br/instagram/agenda.json', json: true, timeout: 20000 }); } catch (e) { agenda = null; }
if (typeof agenda === 'string') { try { agenda = JSON.parse(agenda); } catch (e) { agenda = null; } }
if (!Array.isArray(agenda)) return [{ json: { publicou: false, motivo: 'sem_agenda' } }];
const p = postDeHoje(agenda, agora, teste ? { feitos: mem.feitos } : mem);
if (!p) return [{ json: { publicou: false, motivo: 'nada_hoje', itens: agenda.length } }];
if (teste) return [{ json: { publicou: false, motivo: 'teste', id: p.id, midiaUrl: 'https://www.temdescontos.com.br' + (p.video || p.imagem), reel: !!p.video, legenda: p.legenda } }];
// Reel só com INSTAGRAM_REEL=sim; desligado, o item fica esperando (não conta tentativa).
if (p.video && !reelLigado($env)) return [{ json: { publicou: false, motivo: 'reel_desligado', id: p.id } }];
let id = null;
try { id = p.video ? await publicarReel(this.helpers, $env, 'https://www.temdescontos.com.br' + p.video, p.legenda) : await publicarNoFeed(this.helpers, $env, 'https://www.temdescontos.com.br' + p.imagem, p.legenda); } catch (e) { id = null; }
anotarTentativa(mem, p.id, !!id);
// 3ª falha do dia (13/11): avisa no rascunho, porque o post não sai mais hoje.
const aviso = id ? null : avisoDeFalha(p, mem.tentativas.n[p.id]);
return [{ json: { publicou: !!id, id: p.id, reel: !!p.video, midia: id, tentativa: id ? undefined : mem.tentativas.n[p.id], avisar: !!(aviso && $env.GRUPO_RASCUNHO), grupo: $env.GRUPO_RASCUNHO, texto: aviso } }];
